// Illustrative commitment: bind to a value without revealing it (SHA-256)
const c=require('node:crypto');
const commit=c.createHash('sha256').update("age"+'|'+"31"+'|'+"s-4471").digest('hex');
console.log('commitment:',commit.slice(0,24)+'…');
console.log('hides value:',commit.indexOf("31")<0);

